actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate Louisiana additions
            double additions = 0.0;

            // Louisiana requires addback of:
            // - Federal interest income (taxable to Louisiana)
            // - State income tax refunds previously deducted
            // - Certain expenses related to tax-exempt income

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += result.state_tax_refunds;

            apportionment.state_additions = additions;

            // Calculate Louisiana subtractions
            double subtractions = 0.0;

            // NEW 2025: $20,000 standard deduction
            subtractions += apportionment.la_standard_deduction;

            // Louisiana allows subtraction of:
            // - $20,000 standard deduction (NEW for 2025)
            // - Louisiana municipal bond interest (exempt for LA purposes)
            // - Louisiana net operating loss deduction (if applicable)
            // - Qualified property immediate expensing (if elected for 2025+)
            // - Research and experimental expenditures (if elected for 2025+)

            // Example additional subtractions (would be calculated from entity fields):
            // subtractions += revenue.la_municipal_interest;
            // subtractions += result.la_nol_deduction;
            // subtractions += result.qualified_property_expensing; // NEW 2025 option

            apportionment.state_subtractions = subtractions;

            // Louisiana uses 5.5% flat rate (NEW for 2025, replaced graduated rates)
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract Louisiana state credits
            // NOTE: Many credits were eliminated or limited in 2025 tax reform
            // Remaining credits include limited versions of:
            // - Jobs creation credit (significantly reduced)
            // - Historic preservation credit (capped)
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
